44		}
45		loc := time.FixedZone("UTC+8", 8*60*60)
46		expiryTZ := expiryOK.In(loc)
47		if expiryTZ.Equal(expiryOK) && expiryTZ.String() == expiryOK.String() {
48			t.Fatalf("test setup: timezone representation did not differ")
49		}
50		got, err := s.Reserve("c1", "r1", "part1", 5, expiryTZ, nowOK.Add(5*day))
