59	// TestReserveRetryAfterUseAndCancelReturnsFirstResult 对应用户给出的典型例子：
60	// 库存十件，预留五件，使用两件后取消，原样重试仍返回首次的五件承诺；查询继续
61	// 显示已用两件、已取消、实物剩余八件、有效占用为零。
62	func TestReserveRetryAfterUseAndCancelReturnsFirstResult(t *testing.T) {
63		s := newStore(t)
64		first, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK)
65		if err != nil {
66			t.Fatalf("reserve: %v", err)
67		}
