69			t.Fatalf("use: %v", err)
70		}
71		if _, err := s.Cancel("c1", nowOK); err != nil {
72			t.Fatalf("cancel: %v", err)
73		}
74	
75		retry, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK.Add(day))
76		if err != nil {
77			t.Fatalf("retry after use+cancel: %v", err)
78		}
79		// 取回首次成功时的完整承诺：已用数量仍为零、取消标记仍为否。
80		if retry != first || retry.Used != 0 || retry.Canceled || retry.Quantity != 5 {
81			t.Fatalf("retry = %+v, want first %+v", retry, first)
82		}
83	
84		// 查询继续反映承诺的当前状态。
85		st, err := s.PartStatus("part1", nowOK)
86		if err != nil {
87			t.Fatalf("part status: %v", err)
88		}
89		if st.PhysicalRemaining != 8 {
90			t.Fatalf("physical remaining = %d, want 8", st.PhysicalRemaining)
91		}
92		if st.ActiveOccupied != 0 || st.Committable != 8 {
93			t.Fatalf("occupancy not released: occupied=%d committable=%d", st.ActiveOccupied, st.Committable)
94		}
95		if len(st.Details) != 1 {
96			t.Fatalf("details = %d, want 1", len(st.Details))
97		}
98		d := st.Details[0]
99		if d.Status != CommitmentCanceled || d.UsedQuantity != 2 || d.RemainingQuantity != 3 {
100			t.Fatalf("current detail = %+v, want canceled/used=2/remaining=3", d)
101		}
102		// 重试没有恢复占用或补回实物。
103		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 0 {
104			t.Fatalf("retry restored released state: %+v", st)
105		}
106	}
