129	// TestReserveRetryIgnoresLaterEligibilityAndStock 验证请求过保、库存不足后，
130	// 原样重试仍只取回旧结果，首次成功的资格与库存依据不被重试时刻覆盖。
131	func TestReserveRetryIgnoresLaterEligibilityAndStock(t *testing.T) {
132		s := newStore(t)
133		first, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK)
134		if err != nil {
135			t.Fatalf("reserve: %v", err)
136		}
137		// 另一笔承诺占满剩余可承诺量。
138		if _, err := s.Reserve("c2", "r1", "part1", 5, expiryOK, nowOK); err != nil {
139			t.Fatalf("reserve c2: %v", err)
140		}
141		st, _ := s.PartStatus("part1", nowOK)
142		if st.Committable != 0 {
143			t.Fatalf("setup: committable = %d, want 0", st.Committable)
144		}
145		// 请求此时已过保（保修 30 天，now = 第 31 天），且无库存可承诺。
146		retry, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, t0.Add(31*day))
147		if err != nil {
