152		}
153		// 重试不追加历史，首次成功依据保持不变。
154		h, _ := s.RequestHistory("r1")
155		if len(h) != 2 || !h[0].Success {
156			t.Fatalf("history after retry = %+v", h)
157		}
158		if h[0].Eligibility == nil || !h[0].Eligibility.Eligible ||
159			h[0].StockBasis == nil || h[0].StockBasis.PhysicalRemaining != 10 {
160			t.Fatalf("first basis overwritten: %+v", h[0])
161		}
