164	// TestReserveConflictTakesPrecedenceOverInvalidParams 验证已成功编号只要改了
165	// 请求、备件、数量或到期时刻，即使新参数本身非法，也一律按编号冲突处理。
166	func TestReserveConflictTakesPrecedenceOverInvalidParams(t *testing.T) {
167		s := newStore(t)
168		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
169			t.Fatalf("reserve: %v", err)
170		}
171	
172		cases := []struct {
173			name      string
174			requestID string
175			partID    string
176			quantity  int
177			expiry    time.Time
178		}{
179			{"empty request", "", "part1", 5, expiryOK},
180			{"unknown request", "rMissing", "part1", 5, expiryOK},
181			{"unknown part", "r1", "partMissing", 5, expiryOK},
182			{"zero quantity", "r1", "part1", 0, expiryOK},
183			{"negative quantity", "r1", "part1", -1, expiryOK},
184			{"past expiry", "r1", "part1", 5, nowOK.Add(-time.Second)},
185			{"expiry equal now", "r1", "part1", 5, nowOK},
186		}
187		for _, tc := range cases {
188			t.Run(tc.name, func(t *testing.T) {
189				_, err := s.Reserve("c1", tc.requestID, tc.partID, tc.quantity, tc.expiry, nowOK)
190				if !errors.Is(err, ErrConflict) {
191					t.Fatalf("got %v, want ErrConflict", err)
192				}
193			})
194		}
195	
196		// 冲突不改变承诺与库存。
197		st, _ := s.PartStatus("part1", nowOK)
198		if st.ActiveOccupied != 5 || st.PhysicalRemaining != 10 {
199			t.Fatalf("conflict changed state: %+v", st)
200		}
201		// 指定已知请求的冲突各记一条；空请求与未知请求不创建请求和历史。
202		h1, _ := s.RequestHistory("r1")
203		// 1 条成功 + 未知备件/零数量/负数量/过去到期/等于到期 共 5 条冲突。
204		if len(h1) != 6 {
205			t.Fatalf("r1 history len = %d, want 6", len(h1))
206		}
207		for _, rec := range h1[1:] {
208			if rec.Success || rec.Error != HistoryErrorConflict ||
209				rec.Eligibility != nil || rec.StockBasis != nil {
210				t.Fatalf("bad conflict record: %+v", rec)
211			}
212		}
213		if _, err := s.RequestHistory("rMissing"); !errors.Is(err, ErrNotFound) {
214			t.Fatalf("unknown request should not be created by conflict: %v", err)
215		}
216	}
217	
218	// TestReserveRetryResultIsImmutable 验证调用方修改首次返回值或重试返回值，
219	// 都不能改变以后取回的首次结果、当前承诺和预留历史。
220	func TestReserveRetryResultIsImmutable(t *testing.T) {
221		s := newStore(t)
222		first, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK)
223		if err != nil {
224			t.Fatalf("reserve: %v", err)
225		}
226		first.Used = 99
227		first.Canceled = true
228		first.Quantity = 1
229		retry, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK)
230		if err != nil {
231			t.Fatalf("retry: %v", err)
232		}
233		if retry.Used != 0 || retry.Canceled || retry.Quantity != 5 {
234			t.Fatalf("first return value mutation leaked: %+v", retry)
235		}
236		retry.Used = 88
237		again, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, expiryOK)
238		if err != nil {
239			t.Fatalf("retry again: %v", err)
240		}
241		if again.Used != 0 || again.Canceled || again.Quantity != 5 {
242			t.Fatalf("retry return value mutation leaked: %+v", again)
243		}
244		cur, _ := s.Commitment("c1")
245		if cur.Used != 0 || cur.Canceled || cur.Quantity != 5 {
246			t.Fatalf("current commitment mutated: %+v", cur)
247		}
248		h, _ := s.RequestHistory("r1")
249		if len(h) != 1 || h[0].Quantity != 5 || !h[0].Success {
250			t.Fatalf("history mutated: %+v", h)
251		}
252	}
253	
254	// TestReserveFailedSubmissionRemainsReusable 验证尚未成功占用的编号继续按本次
255	// 参数、资格和库存判断，失败后允许用该编号再次提交，失败不固定成永久结果。
256	func TestReserveFailedSubmissionRemainsReusable(t *testing.T) {
257		s := newStore(t)
258		// 参数非法失败。
259		if _, err := s.Reserve("c1", "r1", "part1", 0, expiryOK, nowOK); !errors.Is(err, ErrInvalidParam) {
260			t.Fatalf("zero quantity: %v", err)
261		}
262		// 库存不足失败。
263		if _, err := s.Reserve("c1", "r1", "part1", 11, expiryOK, nowOK); !errors.Is(err, ErrInsufficientStock) {
264			t.Fatalf("over stock: %v", err)
265		}
266		// 请求过保失败。
267		if _, err := s.Reserve("c1", "r1", "part1", 1, expiryOK, t0.Add(31*day)); !errors.Is(err, ErrIneligible) {
268			t.Fatalf("ineligible: %v", err)
269		}
270		// 条件满足后同编号首次成功。
271		first, err := s.Reserve("c1", "r1", "part1", 4, expiryOK, nowOK)
272		if err != nil {
273			t.Fatalf("reserve after failures: %v", err)
274		}
275		if first.Quantity != 4 {
276			t.Fatalf("commitment = %+v", first)
277		}
278		st, _ := s.PartStatus("part1", nowOK)
279		if st.ActiveOccupied != 4 {
280			t.Fatalf("occupied = %d, want 4", st.ActiveOccupied)
281		}
282		// 成功之后，再用曾经失败过的参数提交即按冲突处理。
283		if _, err := s.Reserve("c1", "r1", "part1", 11, expiryOK, nowOK); !errors.Is(err, ErrConflict) {
284			t.Fatalf("reused id after success: got %v, want ErrConflict", err)
285		}
286	}
287	
288	// TestReserveRetryConcurrentWithUseAndCancel 验证并发原样重试只能取回首次成功值，
289	// 且只产生一次占用和一条成功历史；查询反映实际完成的使用与取消。
290	func TestReserveRetryConcurrentWithUseAndCancel(t *testing.T) {
291		s := newStore(t)
292		first, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK)
293		if err != nil {
294			t.Fatalf("reserve: %v", err)
295		}
296	
297		const retryN = 16
298		var wg sync.WaitGroup
299		var mu sync.Mutex
300		var badRetries int
301		useOK := 0
302		for i := 0; i < retryN; i++ {
303			wg.Add(1)
304			go func(i int) {
305				defer wg.Done()
306				got, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, expiryOK.Add(time.Duration(i)*time.Hour))
307				mu.Lock()
308				defer mu.Unlock()
309				if err != nil || got != first {
310					badRetries++
311				}
312			}(i)
313		}
314		for i := 0; i < 2; i++ {
315			wg.Add(1)
316			go func(i int) {
317				defer wg.Done()
318				_, err := s.Use(fmt.Sprintf("u%d", i), "c1", 1, nowOK)
319				mu.Lock()
320				defer mu.Unlock()
321				switch {
322				case err == nil:
323					useOK++
324				case errors.Is(err, ErrCommitmentClosed), errors.Is(err, ErrUsageExceeded):
325				default:
326					t.Errorf("unexpected use error: %v", err)
327				}
328			}(i)
329		}
330		wg.Add(1)
331		go func() {
332			defer wg.Done()
333			if _, err := s.Cancel("c1", nowOK); err != nil {
334				t.Errorf("cancel: %v", err)
335			}
336		}()
337		wg.Wait()
338	
339		if badRetries != 0 {
340			t.Fatalf("%d retries did not return the first result", badRetries)
341		}
342		// 只有一条成功历史，重试不追加。
343		h, _ := s.RequestHistory("r1")
344		if len(h) != 1 || !h[0].Success {
345			t.Fatalf("history = %+v, want single success", h)
346		}
347		// 查询反映实际完成的操作：取消后占用为零，实物只扣减成功使用量。
348		st, _ := s.PartStatus("part1", nowOK)
349		if st.ActiveOccupied != 0 || st.PhysicalRemaining != 10-useOK {
350			t.Fatalf("state after concurrent retry/use/cancel: used=%d status=%+v", useOK, st)
351		}
352		d := st.Details[0]
353		if d.Status != CommitmentCanceled || d.UsedQuantity != useOK {
354			t.Fatalf("detail = %+v, want canceled with used=%d", d, useOK)
355		}
356	}
