			calls := contentionCalls(commitID, "part1", contentA, contentB, n)
			results := fanOutConcurrentReserve(s, calls)
			assertReserveContentionSingleWinner(t, s, commitID, calls, results, 10, contentA, contentB)
		})
	}
}

